NEW_CASES = {'rc_pretag_issue86_root_identity_cases.Issue86RootIdentityCases': ('test_actual_m_identity_and_fresh_historical_validation', 'test_exact_ordered_d_i_j_selection', 'test_wrong_topology_delegates_without_content', 'test_nested_merges_and_correction_chains_never_admit', 'test_extra_missing_and_changed_paths_reject', 'test_source_pins_and_caps_match_working_tree', 'test_normalize_restores_exact_m_bytes_and_rejects_drift', 'test_rust_delta_is_exactly_the_eight_snapshot_files')}
